 const reg=api.createQuestionDeliveryRegistry(root),open=(i,o=owner,questions=q)=>reg.open(o,tag.scopeOf(o),questions,{ownerToken:token,eventId:'limit-'+i,agentId:tag.scopeOf(o),generationToken:{},attemptToken:{},clientId:'unit'});
 for(let i=0;i<40;i++)open(i);assert(reg.stats().entries===32,'32 per-owner cache limit',reg.stats());reg.dispose();
 const many=api.createQuestionDeliveryRegistry(root);for(let i=0;i<80;i++){const o=tag.createScope(root,'many-'+i).ctx;many.open(o,'many-'+i,q,{ownerToken:token,eventId:'e'+i,agentId:'many-'+i,generationToken:{},attemptToken:{},clientId:'c'})}assert(many.stats().entries===64,'64 global cache limit',many.stats());many.dispose();
 const total=api.createQuestionDeliveryRegistry(root);for(let i=0;i<32;i++){const r=total.open(owner,'bound-a',q,{ownerToken:token,eventId:'size'+i,agentId:'bound-a',generationToken:{},attemptToken:{},clientId:'c'});total.save(r,{index:0,drafts:[{selected:[],custom:'界'.repeat(19000),skipped:false}]})}assert(total.stats().bytes<=1048576&&total.stats().entries<32,'1MiB aggregate UTF8 cache cap',total.stats());total.dispose();
 const utf=api.createQuestionDeliveryRegistry(root),u=utf.open(owner,'bound-a',q,{ownerToken:token,eventId:'utf',agentId:'bound-a',generationToken:{},attemptToken:{},clientId:'c'});assert(!utf.save(u,{index:0,drafts:[{selected:[],custom:'界'.repeat(22000),skipped:false}]}),'64KiB record uses UTF8 not string length');assert(utf.stats().entries===0,'oversize rejected without truncation');utf.dispose();
 for(const [label,value] of [['deep',Array.from({length:40}).reduce(x=>[x],0)],['unsupported',new Date()],['nodes',Array.from({length:8200},()=>0)],['string','x'.repeat(65537)]]){let refused=false;try{api.questionCanonical(value)}catch{refused=true}assert(refused,'canonical refuses '+label)}
 // Use actual monotonic clock value beyond recorded deadline to exercise production purge, no altered TTL constant.
